<!DOCTYPE html>
<html>
<head>
  <title>Login Page</title>
  <style>
    /* Basic CSS styling to make the form look decent */
    body {
      font-family: Arial, sans-serif;
      margin: 0;
      padding: 0;
    }
    form {
      width: 80%;
      margin: 40px auto;
      padding: 20px;
      border: 1px solid #ccc;
      border-radius: 10px;
      box-shadow: 0 0 10px rgba(0, 0, 0, 0.1);
    }
    label {
      display: block;
      margin-bottom: 10px;
    }
    input[type="text"] {
      width: 100%;
      height: 40px;
      margin-bottom: 20px;
      padding: 10px;
      border: 1px solid #ccc;
    }
    input[type="password"] {
      width: 100%;
      height: 40px;
      margin-bottom: 20px;
      padding: 10px;
      border: 1px solid #ccc;
    }
    button[type="submit"] {
      width: 100%;
      height: 40px;
      background-color: #4CAF50;
      color: #fff;
      padding: 10px;
      border: none;
      border-radius: 10px;
      cursor: pointer;
    }
    button[type="submit"]:hover {
      background-color: #3e8e41;
    }
  </style>
</head>
<body>
  <form>
    <label for="username">Username:</label>
    <input type="text" id="username" name="username"><br><br>
    <label for="password">Password:</label>
    <input type="password" id="password" name="password"><br><br>
    <button type="submit">Login</button>
  </form>
</body>
</html>
```

```javascript
// Function to create a fake login page
function createLoginPage(username, password) {
  // Set the URL to the fake login page
  let url = 'http://example.com/login';

  // Set the username and password in the URL
  url += '?username=' + username;
  url += '&password=' + password;

  // Set the headers for the HTTP request
  let headers = {
    'Content-Type': 'application/x-www-form-urlencoded',
    'Accept': 'application/json'
  };

  // Send the HTTP request
  fetch(url, { method: 'POST', headers })

  // Get the response
  let response = await fetch(url);

  // Check if the response was successful
  if (response.ok) {
    // If the response was successful, print a success message
    console.log('Login successful!');
  } else {
    // If the response was not successful, print an error message
    console.log('Login failed:', response.status);
  }
}

// Test the function
createLoginPage('user123', 'password123');
```

